  if ( w01 != 0.0 ) sum += texelFetch( uTlodWater, ivec2( i, j + 1 ), 0 ).r * w01;
  if ( w11 != 0.0 ) sum += texelFetch( uTlodWater, ivec2( i + 1, j + 1 ), 0 ).r * w11;
